// ============================================================
// CORE LLM — NORMALIZA GEMINI
//
// Recebe a API selecionada pela SP e os prompts do fluxo pai.
// Mantém o contador Gemini para cada ciclo:
//   1. Primeira chamada: tentativa 1.
//   2. Falha na primeira chamada: tentativa 2.
//   3. Falha Cloudflare: inicia novo ciclo na tentativa 1.
// ============================================================


// ------------------------------------------------------------
// 1. Recupera a API retornada pela procedure
// ------------------------------------------------------------

const items = $input.all();

let api = items[0]?.json;

// A procedure pode retornar a linha dentro de um array.
if (Array.isArray(api)) {
  api = api[0];
}

if (!api?.dsc_api_key) {
  throw new Error('CORE LLM: API Key Gemini não encontrada.');
}

if (!api?.dsc_url_servico) {
  throw new Error('CORE LLM: modelo Gemini não encontrado.');
}


// ------------------------------------------------------------
// 2. Recupera e valida os prompts do fluxo pai
// ------------------------------------------------------------

const entrada = $('Start LLM').first().json;

const system = String(
  entrada.MSG_Prompt_System ?? ''
).trim();

const user = String(
  entrada.MSG_Prompt_User ?? ''
).trim();

if (!system || !user) {
  throw new Error(
    'CORE LLM: prompts obrigatórios não recebidos.'
  );
}


// ------------------------------------------------------------
// 3. Normaliza o nome do modelo Gemini
// ------------------------------------------------------------

const modelo = String(api.dsc_url_servico)
  .replace(/^models\//, '')
  .trim();

if (!modelo) {
  throw new Error('CORE LLM: modelo Gemini inválido.');
}


// ------------------------------------------------------------
// 4. Define o estado inicial do ciclo Gemini
// ------------------------------------------------------------

let core = {
  tentativa_gemini: 1,
  max_tentativas_gemini: 2
};


// ------------------------------------------------------------
// 5. Recupera o estado preparado após a última falha Gemini
// ------------------------------------------------------------
//
// retry_gemini:
//   CONTADOR RETRY preparou a segunda tentativa Gemini.
//
// fallback_cloudflare:
//   As duas tentativas Gemini falharam. Se Normaliza voltou a
//   executar depois disso, o retorno veio da rota Cloudflare;
//   nesse caso, usa o novo ciclo preparado por IF RETRY.
// ------------------------------------------------------------

let ultimoContador = null;

try {
  ultimoContador = $('CONTADOR RETRY').last().json;
} catch {
  // Primeira chamada: CONTADOR RETRY ainda não executou.
}

if (ultimoContador?._route === 'retry_gemini') {
  if (!ultimoContador._core) {
    throw new Error(
      'CORE LLM: contador da próxima tentativa Gemini ausente.'
    );
  }

  core = {
    ...core,
    ...ultimoContador._core
  };
} else if (ultimoContador?._route === 'fallback_cloudflare') {
  let retornoCloudflare;

  try {
    retornoCloudflare = $('IF RETRY').last().json;
  } catch {
    throw new Error(
      'CORE LLM: retorno da Cloudflare sem contador de novo ciclo.'
    );
  }

  if (
    retornoCloudflare?._route !== 'retry_gemini' ||
    !retornoCloudflare.contexto?._core
  ) {
    throw new Error(
      'CORE LLM: estado do novo ciclo Gemini inválido.'
    );
  }

  core = {
    ...core,
    ...retornoCloudflare.contexto._core
  };
}


// ------------------------------------------------------------
// 6. Valida o contador antes de chamar o Gemini
// ------------------------------------------------------------

core.tentativa_gemini = Number(core.tentativa_gemini);
core.max_tentativas_gemini = Number(core.max_tentativas_gemini);

if (
  !Number.isInteger(core.tentativa_gemini) ||
  !Number.isInteger(core.max_tentativas_gemini) ||
  core.tentativa_gemini < 1 ||
  core.max_tentativas_gemini !== 2 ||
  core.tentativa_gemini > core.max_tentativas_gemini
) {
  throw new Error(
    'CORE LLM: contador de tentativas Gemini inválido.'
  );
}


// ------------------------------------------------------------
// 7. Prepara os dados para o node HTTP Gemini
// ------------------------------------------------------------

return [
  {
    json: {
      api_id: api.id,
      api_key: api.dsc_api_key,
      modelo,
      txt_CMD_System: system,
      txt_CMD_User: user,
      _core: core
    }
  }
];

const item = $input.first()?.json ?? {};
const partes = item.candidates?.[0]?.content?.parts ?? [];
const textoGemini = Array.isArray(partes)
  ? partes.filter(parte => typeof parte?.text === 'string').map(parte => parte.text).join('')
  : '';
const texto = typeof item.text === 'string' ? item.text.trim() : textoGemini.trim();

if (!texto) throw new Error('CORE LLM: resposta textual vazia ou inválida.');

const tokens = item.tokens
  ?? item.usage?.total_tokens
  ?? item.usage?.totalTokens
  ?? item.usageMetadata?.totalTokenCount
  ?? null;

return [{
  json: {
    text: texto,
    modelo: item.modelo ?? item.modelVersion ?? null,
    tokens,
    provedor: item.provedor ?? 'gemini',
  },
}];

// Recupera a falha e a configuração Gemini desta tentativa.
const erro = $('Interpretar Gemini').last().json;
const gemini = $('Normaliza').last().json;
const entrada = $('Start LLM').first().json;

const tentativaAtual = Number(gemini._core?.tentativa_gemini ?? 1);
const maxTentativas = 2;

if (!Number.isInteger(tentativaAtual) || tentativaAtual < 1) {
  throw new Error('CORE LLM: contador Gemini inválido.');
}

// Após a primeira falha, libera a segunda tentativa.
// Após a segunda falha, encaminha para a Cloudflare.
const tentarGeminiNovamente = tentativaAtual < maxTentativas;

return [{
  json: {
    _route: tentarGeminiNovamente
      ? 'retry_gemini'
      : 'fallback_cloudflare',

    api_id_gemini: erro.api_id ?? null,
    erro_gemini: erro.erro ?? 'Falha Gemini sem diagnóstico.',

    MSG_Prompt_System: entrada.MSG_Prompt_System,
    MSG_Prompt_User: entrada.MSG_Prompt_User,

    _core: {
      tentativa_gemini: tentarGeminiNovamente
        ? tentativaAtual + 1
        : tentativaAtual,
      max_tentativas_gemini: maxTentativas
    }
  }
}];

// Recebe o erro produzido pela chamada Cloudflare.
const item = $input.first()?.json ?? {};
const contexto = item.contexto;
const core = contexto?._core;

// Confirma que este node foi acionado pelo caminho esperado.
if (item.provedor !== 'cloudflare' || item._route !== 'error') {
  throw new Error(
    'CORE LLM: entrada fora da rota de falha Cloudflare.'
  );
}

if (!contexto || !core) {
  throw new Error(
    'CORE LLM: contexto de tentativas ausente.'
  );
}

// Cada novo ciclo começa com duas tentativas Gemini disponíveis.
const maxTentativasGemini = 2;

return [
  {
    json: {
      ...item,

      // Identifica o retorno ao fluxo Gemini.
      _route: 'retry_gemini',

      contexto: {
        ...contexto,

        _core: {
          ...core,

          // Reinicia o contador para o novo ciclo.
          tentativa_gemini: 1,
          max_tentativas_gemini: maxTentativasGemini,

          ultimo_provedor: 'cloudflare',
          motivo_retorno: 'falha_cloudflare',

          // Mantém somente informações úteis para diagnóstico.
          ultimo_erro_cloudflare: {
            codigo: item.code ?? null,
            http_status: item.status_code ?? null
          }
        }
      }
    }
  }
];

function encontrarRegistro(valor, profundidade = 0) {
  if (profundidade > 6 || valor == null || typeof valor !== 'object') return null;
  if (!Array.isArray(valor) && Object.prototype.hasOwnProperty.call(valor, 'dsc_api_key')) return valor;
  for (const item of Object.values(valor)) {
    const registro = encontrarRegistro(item, profundidade + 1);
    if (registro) return registro;
  }
  return null;
}

const api = encontrarRegistro($input.all().map(item => item.json));
if (!api || api.id == null) throw new Error('CORE Cloudflare: nenhuma conta disponível na SP.');

const accountId = String(api.dsc_api_key ?? '').trim();
const apiToken = String(api.dsc_api_secret ?? '').trim();
if (!/^[a-f0-9]{32}$/i.test(accountId)) throw new Error('CORE Cloudflare: Account ID ausente ou inválido no cadastro.');
if (!apiToken) throw new Error('CORE Cloudflare: token ausente no cadastro.');

const entrada = $('Start LLM').first().json;
const system = String(entrada.MSG_Prompt_System ?? '').trim();
const user = String(entrada.MSG_Prompt_User ?? '').trim();
if (!system || !user) throw new Error('CORE Cloudflare: prompts de entrada ausentes.');

let core = { tentativa_gemini: 1, max_tentativas_gemini: 5 };
try {
  const anterior = $('IF RETRY').last().json.contexto?._core;
  if (anterior) core = { ...core, ...anterior };
} catch {}

return [{
  json: {
    contexto: {
      account_id: accountId,
      api_id: api.id,
      api_token: apiToken,
      modelo: '@cf/meta/llama-3.3-70b-instruct-fp8-fast',
      request_body: {
        messages: [
          { role: 'system', content: system },
          { role: 'user', content: user },
        ],
        max_tokens: (() => { const value = Number($('Start LLM').first().json.MSG_Max_Tokens); return Number.isInteger(value) && value > 0 ? value : 2048; })(),
        stream: false,
      },
      _core: core,
    },
  },
}];

const payload = $json ?? {};
const gemini = $('Normaliza').first().json;
const candidates = payload.candidates ?? payload.body?.candidates ?? [];
const parts = candidates[0]?.content?.parts ?? [];
const texto = parts.map(p => p?.text ?? '').join('').trim();
const rawErro = payload.error?.message ?? payload.error ?? payload.message ?? payload.body?.error?.message ?? '';
const sucesso = !rawErro && texto.length > 0;
const statusCode = Number(payload.statusCode ?? payload.status ?? payload.error?.code ?? payload.error?.statusCode ?? payload.error?.httpCode ?? 0) || null;
return [{ json: { ...payload, _route: sucesso ? 'success' : 'error', api_id: gemini.api_id, provedor: 'gemini', fallback_provedor: 'cloudflare', modelo: gemini.modelo ?? null, text: sucesso ? texto : '', tokens: payload.usageMetadata?.totalTokenCount ?? null, status_code: statusCode, erro: sucesso ? null : String(rawErro || 'Gemini retornou resposta vazia ou sem candidates válidos.').trim().slice(0, 1000), execution_id: $execution.id, timestamp: $now.toISO(), alerta_tipo: sucesso ? null : 'gemini_fallback' } }];

const contexto = $('Preparar Conta Cloudflare').last().json.contexto;
const response = $json ?? {};
const status = Number(response.statusCode ?? 0);
const body = response.body ?? response;
const result = body?.result ?? {};
const text = typeof result.response === 'string' ? result.response.trim() : '';

if (status >= 200 && status < 300 && body.success !== false && text) {
  return [{
    json: {
      _route: 'success',
      provedor: 'cloudflare',
      contexto,
      text,
      modelo: contexto.modelo,
      usage: result.usage ?? null,
    },
  }];
}

let code;
if (status === 429) code = 'LIMIT_EXCEEDED';
else if (status === 401 || status === 403) code = 'AUTHENTICATION_FAILED';
else if (status === 404) code = 'MODEL_UNAVAILABLE';
else if ([408, 425, 500, 502, 503, 504].includes(status) || status === 0) code = 'UPSTREAM_UNAVAILABLE';
else if (status >= 200 && status < 300) code = 'INVALID_RESPONSE';
else if (status >= 400) code = 'CLOUDFLARE_API_ERROR';
else code = 'COMMUNICATION_ERROR';

return [{
  json: {
    _route: 'error',
    provedor: 'cloudflare',
    contexto,
    code,
    status_code: status || null,
    diagnostic: 'Falha na chamada Cloudflare Workers AI.',
  },
}];
